import type { SimulationEvent } from '../contracts/events';
import type { MatchDTO, MatchSettings, PlayerHoleScore, PlayerProfile } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { GameplayStateMachine } from './StateMachine';
import { ScoreManager } from './ScoreManager';
import { TurnManager } from './TurnManager';

export class MatchManager {
  private readonly scores = new ScoreManager();
  private readonly turns = new TurnManager();
  private machine = new GameplayStateMachine('lobby');

  createMatch(id: string, settings: MatchSettings, players: readonly PlayerProfile[]): MatchDTO {
    if (players.length < 1 || players.length > settings.maxPlayers) throw new Error('Invalid player count');
    this.machine = new GameplayStateMachine('lobby');
    return {
      id,
      phase: 'lobby',
      settings,
      players: players.map(player => ({ ...player, connected: true, totalStrokes: 0, holeScores: [] })),
      currentHoleIndex: 0,
    };
  }

  startMatch(match: MatchDTO, course: Course, now = Date.now()): MatchDTO {
    if (course.id !== match.settings.courseId) throw new Error('Course does not match match settings');
    const firstHole = course.holes[0];
    if (!firstHole) throw new Error('Course has no holes');
    this.machine = new GameplayStateMachine(match.phase);
    this.machine.transition('hole-intro');
    return this.prepareHole({ ...match, phase: this.machine.phase, startedAt: now }, firstHole);
  }

  beginAiming(match: MatchDTO, hole: Hole): MatchDTO {
    this.sync(match.phase);
    this.machine.transition('aiming');
    return { ...match, phase: this.machine.phase, activePlayerId: this.turns.firstEligiblePlayer(match, hole.id) };
  }

  markShotSubmitted(match: MatchDTO): MatchDTO {
    this.sync(match.phase);
    this.machine.transition('simulating');
    return { ...match, phase: this.machine.phase };
  }

  applySimulationEvent(match: MatchDTO, course: Course, event: SimulationEvent, now = Date.now()): MatchDTO {
    const hole = course.holes[match.currentHoleIndex];
    if (!hole) throw new Error('Current hole does not exist');

    if (event.type === 'shot-accepted') {
      return this.updateScore(match, event.command.playerId, hole.id, score => this.scores.recordStroke(score));
    }
    if (event.type === 'ball-reset') {
      return this.updateScore(match, event.playerId, hole.id, score => this.scores.addPenalty(score, event.penaltyStrokes));
    }
    if (event.type === 'ball-holed') {
      const completed = this.updateScore(match, event.playerId, hole.id, score => this.scores.complete(score, now - (match.startedAt ?? now)));
      return this.advanceAfterFinish(completed, course, hole.id, event.playerId, now);
    }
    if (event.type === 'ball-stopped') {
      return this.advanceTurn(match, course, hole.id, event.playerId, now);
    }
    return match;
  }

  enforceStrokeLimit(match: MatchDTO, course: Course, playerId: string, now = Date.now()): MatchDTO {
    const hole = course.holes[match.currentHoleIndex];
    if (!hole) throw new Error('Current hole does not exist');
    const updated = this.updateScore(match, playerId, hole.id, score => this.scores.applyStrokeLimit(score, match.settings.strokeLimitPerHole));
    const score = this.findScore(updated, playerId, hole.id);
    return score.completed ? this.advanceAfterFinish(updated, course, hole.id, playerId, now) : updated;
  }

  pause(match: MatchDTO): MatchDTO {
    this.sync(match.phase);
    this.machine.pause();
    return { ...match, phase: this.machine.phase };
  }

  resume(match: MatchDTO): MatchDTO {
    const phase = this.machine.resume();
    return { ...match, phase };
  }

  private prepareHole(match: MatchDTO, hole: Hole): MatchDTO {
    const players = match.players.map(player => player.holeScores.some(score => score.holeId === hole.id)
      ? player
      : { ...player, holeScores: [...player.holeScores, this.scores.createHoleScore(player.id, hole.id)] });
    return { ...match, players, activePlayerId: undefined };
  }

  private advanceAfterFinish(match: MatchDTO, course: Course, holeId: string, playerId: string, now: number): MatchDTO {
    if (this.turns.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
    return this.advanceTurn(match, course, holeId, playerId, now);
  }

  private advanceTurn(match: MatchDTO, course: Course, holeId: string, currentPlayerId: string, now: number): MatchDTO {
    if (this.turns.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
    this.sync(match.phase);
    if (this.machine.phase === 'simulating') this.machine.transition('aiming');
    return { ...match, phase: this.machine.phase, activePlayerId: this.turns.nextEligiblePlayer(match, holeId, currentPlayerId) };
  }

  private finishHole(match: MatchDTO, course: Course, now: number): MatchDTO {
    this.sync(match.phase);
    if (this.machine.phase === 'simulating' || this.machine.phase === 'aiming') this.machine.transition('hole-results');
    if (match.currentHoleIndex >= course.holes.length - 1) {
      this.machine.transition('match-results');
      return {
        ...match,
        phase: this.machine.phase,
        activePlayerId: undefined,
        finishedAt: now,
        players: match.players.map(player => ({ ...player, totalStrokes: this.scores.totalForPlayer(player) })),
      };
    }
    this.machine.transition('hole-intro');
    const nextIndex = match.currentHoleIndex + 1;
    const nextHole = course.holes[nextIndex];
    if (!nextHole) throw new Error('Next hole does not exist');
    return this.prepareHole({ ...match, phase: this.machine.phase, currentHoleIndex: nextIndex }, nextHole);
  }

  private updateScore(match: MatchDTO, playerId: string, holeId: string, updater: (score: PlayerHoleScore) => PlayerHoleScore): MatchDTO {
    return {
      ...match,
      players: match.players.map(player => {
        if (player.id !== playerId) return player;
        const holeScores = player.holeScores.map(score => score.holeId === holeId ? updater(score) : score);
        return { ...player, holeScores, totalStrokes: holeScores.reduce((sum, score) => sum + score.strokes, 0) };
      }),
    };
  }

  private findScore(match: MatchDTO, playerId: string, holeId: string): PlayerHoleScore {
    const score = match.players.find(player => player.id === playerId)?.holeScores.find(entry => entry.holeId === holeId);
    if (!score) throw new Error(`Missing score for player ${playerId} on hole ${holeId}`);
    return score;
  }

  private sync(phase: MatchDTO['phase']): void {
    if (this.machine.phase !== phase) this.machine = new GameplayStateMachine(phase);
  }
}
